export function writtenDocsFor(topic: string, level: ComprehensionLevel): ComprehensionEcritedoc[] {
  const exact = COMPREHENSION_ECRITE_DOCS.filter(
    (doc) => doc.level === level && doc.themes.includes(topic),
  )
  if (exact.length > 0) return exact
  const sameTheme = COMPREHENSION_ECRITE_DOCS.filter((doc) => doc.themes.includes(topic))
  if (sameTheme.length > 0) return sameTheme
  return COMPREHENSION_ECRITE_DOCS.filter((doc) => doc.level === level)
}
